const ts = require('typescript');
const path = require('path');
const configPath = path.resolve('tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
if (read.error) {
  console.error('readConfig', read.error.messageText);
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, path.dirname(configPath));
const files = [
  'src/i18n/locale/en.ts',
  'src/i18n/locale/th.ts',
  'src/i18n/locale/vn.ts',
  'src/i18n/locale/zh_tw.ts',
  'src/pages/AccountSecurityPage/AccountSecurityPage.tsx',
].map(f => path.resolve(f));
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const wanted = new Set(files);
function dump(kind, diags) {
  const hit = diags.filter(d => d.file && wanted.has(path.resolve(d.file.fileName)));
  console.log(kind, hit.length);
  for (const d of hit) {
    const pos = d.file.getLineAndCharacterOfPosition(d.start || 0);
    console.log(`${path.relative(process.cwd(), d.file.fileName)}:${pos.line + 1}:${pos.character + 1} TS${d.code} ${ts.flattenDiagnosticMessageText(d.messageText, ' ')}`);
  }
}
dump('semantic', program.getSemanticDiagnostics().filter(d => d.file));
dump('syntactic', program.getSyntacticDiagnostics());
dump('suggestion', program.getSuggestionDiagnostics ? program.getOptionsDiagnostics && files.flatMap(f => {
  const sf = program.getSourceFile(f);
  return sf && program.getSuggestionDiagnostics ? program.getSuggestionDiagnostics(sf) : [];
}) : []);
NODE
